"""Loading utilities for DynEoMT dynamic/static pseudo-labels."""

import json
from pathlib import Path


class DynamicTargetStore:
    """Load and cache schema-v2 pseudo-labels generated by ``scripts/``."""

    def __init__(self, root, dataset, required=True):
        self.root = Path(root) if root else None
        self.dataset = str(dataset).lower()
        self.required = bool(required)
        self._cache = {}

    def _path(self, sequence_id):
        if self.root is None:
            return None
        path = self.root / self.dataset / str(sequence_id) / "targets.json"
        return path if path.is_file() else None

    @staticmethod
    def _parse(payload):
        if payload.get("schema_version") != 2:
            raise ValueError(
                f"Unsupported dynamic-target schema: {payload.get('schema_version')!r}"
            )

        frames = {}
        for frame in payload.get("frames", []):
            records = []
            for mask in frame.get("masks", []):
                label = str(mask.get("label", "uncertain")).lower()
                records.append(
                    {
                        "source_id": str(mask["source_id"]),
                        "track_id": str(mask.get("track_id", mask["source_id"])),
                        "category_id": int(mask["category_id"]),
                        "category_name": str(mask.get("category_name", "")),
                        "area": float(mask.get("area", 1.0)),
                        "target": float(label == "dynamic"),
                        "probability": float(mask.get("probability", label == "dynamic")),
                        "valid": label in {"static", "dynamic"},
                        "label": label,
                    }
                )
            frames[Path(frame["frame"]).stem] = records
        return {"frames": frames, "payload": payload}

    def load(self, sequence_id):
        sequence_id = str(sequence_id)
        if sequence_id in self._cache:
            return self._cache[sequence_id]

        path = self._path(sequence_id)
        if path is None:
            if self.required:
                raise FileNotFoundError(
                    f"Missing dynamic targets for {self.dataset}/{sequence_id} in {self.root}"
                )
            self._cache[sequence_id] = None
            return None

        with path.open() as handle:
            parsed = self._parse(json.load(handle))
        parsed["path"] = path
        self._cache[sequence_id] = parsed
        return parsed

    @staticmethod
    def frame_records(targets, file_name):
        if targets is None:
            return []
        return targets["frames"].get(Path(file_name).stem, [])

    def instance_values(self, targets, source_id, file_names):
        source_id = str(source_id)
        values, valid = [], []
        for file_name in file_names:
            record = next(
                (
                    item
                    for item in self.frame_records(targets, file_name)
                    if item["source_id"] == source_id
                ),
                None,
            )
            values.append(float(record["target"]) if record is not None else 0.0)
            valid.append(bool(record["valid"]) if record is not None else False)
        return values, valid

    def category_values(self, targets, category_id, file_names):
        """Area-average component targets for a semantic category."""
        category_id = int(category_id)
        values, valid = [], []
        for file_name in file_names:
            records = [
                item
                for item in self.frame_records(targets, file_name)
                if item["category_id"] == category_id and item["valid"]
            ]
            if not records:
                values.append(0.0)
                valid.append(False)
                continue
            total_area = sum(max(item["area"], 1.0) for item in records)
            weighted_target = sum(
                item["target"] * max(item["area"], 1.0) for item in records
            )
            values.append(float(weighted_target / total_area))
            valid.append(True)
        return values, valid
